@startuml

class Person {
  + personId : int
  + phoneNumber : string
  + keywords : string[]
}

class ResearchInstitution {
  + institutionCode : int
}

class ScientificArticle {
  + doi : string
  + title : string
}

abstract class PeerReviewedPaper {
  + citationCount : int
}

class TechnicalReport {}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

class AuthorRole {
  + position : int
}

class ReviewerRole {}

class Subscription {
}

Person "1" -- "0..*" ResearchInstitution : worksFor
Person "1" -- "0..*" ScientificArticle : author
Person "1" -- "0..*" ScientificArticle : reviewer

ScientificArticle --|> PeerReviewedPaper
ScientificArticle --|> TechnicalReport

PeerReviewedPaper "1" -- "1..*" ReviewerRole
ReviewerRole "1" -- "1" Person

TechnicalReport "1" -- "1" ResearchInstitution : publishedBy

Publisher "1" -- "1..*" Journal : publishes
ResearchInstitution "1" -- "0..*" Subscription
Subscription "1" -- "1" Journal

ScientificArticle "1" -- "1..*" AuthorRole
AuthorRole "1" -- "1" Person

PeerReviewedPaper "1" -- "0..1" Journal : publishedIn

@enduml

